#include <iostream>
using namespace std;

long long gcd(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

long long lcm(long long a, long long b) {
    return a / gcd(a, b) * b;
}

int main() {
    int n;
    cin >> n;
    long long g, l;
    cin >> g;
    l = g;
    for (int i = 1; i < n; i++) {
        long long x;
        cin >> x;
        g = gcd(g, x);
        l = lcm(l, x);
    }
    cout << g << " " << l << endl;
    return 0;
}

